```rust
impl Solution {
    pub fn min_interval(intervals: Vec<Vec<i32>>, queries: Vec<i32>) -> Vec<i32> {
        let mut res = Vec::new();
        for q in &queries {
            let mut cur = -1;
            for interval in &intervals {
                let (l, r) = (interval[0], interval[1]);
                if l <= *q && *q <= r {
                    let len = r - l + 1;
                    if cur == -1 || len < cur {
                        cur = len;
                    }
                }
            }
            res.push(cur);
        }
        res
    }
}
```

