        propagate(treeIdx, lo, hi)
        if (lo == hi) return tree[treeIdx]
        val mid = (lo + hi) / 2
        return if (idx <= mid) {
            queryPoint(2 * treeIdx + 1, lo, mid, idx)
        } else {
            queryPoint(2 * treeIdx + 2, mid + 1, hi, idx)
        }
    }

