class Solution {
    func minInterval(_ intervals: [[Int]], _ queries: [Int]) -> [Int] {
        var intervals = intervals.sorted { $0[0] < $1[0] }
        var minHeap = Heap<(Int, Int)> { $0.0 < $1.0 }
        var res = [Int: Int]()
        var i = 0

        for q in queries.sorted() {
            while i < intervals.count && intervals[i][0] <= q {
                let l = intervals[i][0]
                let r = intervals[i][1]
                minHeap.insert((r - l + 1, r))
                i += 1
            }

            while !minHeap.isEmpty && minHeap.peek()!.1 < q {
                minHeap.remove()
            }
            res[q] = minHeap.isEmpty ? -1 : minHeap.peek()!.0
        }

        return queries.map { res[$0]! }
    }
}

struct Heap<T> {
    var elements: [T] = []
    let comparator: (T, T) -> Bool

    init(comparator: @escaping (T, T) -> Bool) {
        self.comparator = comparator
    }

    var isEmpty: Bool { elements.isEmpty }
    var count: Int { elements.count }

    func peek() -> T? { elements.first }

    mutating func insert(_ value: T) {
        elements.append(value)
        siftUp(from: elements.count - 1)
    }

    mutating func remove() -> T? {
        guard !elements.isEmpty else { return nil }
        if elements.count == 1 { return elements.removeLast() }
        let first = elements[0]
        elements[0] = elements.removeLast()
        siftDown(from: 0)
        return first
    }

    private mutating func siftUp(from index: Int) {
        var child = index
        var parent = (child - 1) / 2
        while child > 0 && comparator(elements[child], elements[parent]) {
            elements.swapAt(child, parent)
            child = parent
            parent = (child - 1) / 2
        }
    }

    private mutating func siftDown(from index: Int) {
        var parent = index
        while true {
            let left = 2 * parent + 1
            let right = 2 * parent + 2
            var candidate = parent
            if left < elements.count && comparator(elements[left], elements[candidate]) {
                candidate = left
            }
            if right < elements.count && comparator(elements[right], elements[candidate]) {
                candidate = right
            }
            if candidate == parent { return }
            elements.swapAt(parent, candidate)
            parent = candidate
        }
    }
}

